const items=$input.all();
const payload=items.length===1 ? items[0].json : null;
const grant=payload?.status_grant;
const valid=payload && typeof payload==='object' && !Array.isArray(payload) && Object.keys(payload).length===1
  && typeof grant==='string' && grant.length>=48 && grant.length<=2048 && /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(grant);
return [{json:valid ? {status_grant:grant,allowed:true} : {allowed:false}}];

const operation="withdrawal";
const success=["OWNER_CONFIRMS_AT_WISE"];
const response = $input.first().json;
const body = response.body;
const fail = code => [{json:{operation,status:'unavailable',code,data:null}}];
if (response.statusCode !== 200 || !body || body.operation !== operation || body.source !== 'shark-ai-wallet') {
  return fail(response.statusCode === 403 ? 'FINANCE_READ_GRANT_DENIED' : 'BACKEND_UNAVAILABLE');
}
const observed = Date.parse(body.timestamp);
if (!Number.isFinite(observed) || observed > Date.now() + 5000 || observed < Date.now() - 300000) return fail('STALE_PROVIDER_STATUS');
if (body.status === 'unavailable') return fail(['VERIFIED_STATEMENT_REQUIRED','VERIFIED_WALLET_REQUIRED'].includes(body.code) ? body.code : 'BACKEND_UNAVAILABLE');
const data = body.data;
if (body.status !== (operation === 'withdrawal' ? 'needs_human' : 'ok') || !success.includes(body.code) || !data || data.provider !== 'wise') return fail('INVALID_PROVIDER_STATUS');
if (operation === 'balance' && (data.status !== 'verified' || data.source !== 'wise_balance_api' || !/^(0|[1-9]\d*)$/.test(data.balance_minor))) return fail('INVALID_PROVIDER_STATUS');
if (operation === 'deposit' && (data.source !== 'wise_balance_statement' || !Number.isSafeInteger(data.count) || data.count < 0)) return fail('INVALID_PROVIDER_STATUS');
if (operation === 'withdrawal' && data.provider_home !== 'https://wise.com/home/') return fail('INVALID_PROVIDER_STATUS');
return [{json:{operation,status:body.status,code:body.code,data,timestamp:body.timestamp,source:body.source}}];
